import { signal, type Signal } from '@angular/core';
import { Subject, type Observable } from 'rxjs';
import { pruneByIds } from '../../engine/rows';
import type { TableCore, TableFeatureSpec } from '../../engine/types';
import type { RenderRow, RowId, TrackByFn } from '../types';

export interface WithExpansionConfig<TRow> {
  /** Reads a row's nested children. Default: `(row as { children?: TRow[] }).children`. */
  childrenAccessor?: (row: TRow) => TRow[] | undefined;
  /**
   * Decides whether a row should render the expand toggle, independent of whether its
   * children are loaded yet. Use this for lazy-loaded children (fetched on expand), where
   * `childrenAccessor` legitimately returns `undefined`/`[]` until the row has been opened
   * at least once. Default: derived from `childrenAccessor` (non-empty array required).
   */
  isExpandable?: (row: TRow) => boolean;
}

/** The slice of the core store this feature reads. */
type ExpansionInput<TRow> = Pick<TableCore<TRow>, 'rows' | 'trackBy'>;

export interface ExpansionMembers {
  readonly expandedRows: Signal<Set<RowId>>;

  // Additive-only: every id expanded at least once. Never shrinks on collapse — lets
  // consumers gate lazy-then-persist detail-panel mounting on `everExpanded().has(id)`
  // instead of `isExpanded`. See docs/1-state/features/expansion.md.
  readonly everExpanded: Signal<Set<RowId>>;

  readonly rowExpanded: Observable<RowId>;

  toggleExpanded(rowId: RowId): void;
  expandAll(): void;
  collapseAll(): void;
}

function hasChildrenField<TRow>(
  row: TRow
): row is TRow & { children?: TRow[] } {
  return typeof row === 'object' && row !== null && 'children' in row;
}

function defaultChildrenAccessor<TRow>(row: TRow): TRow[] | undefined {
  return hasChildrenField(row) ? row.children : undefined;
}

function hasNonEmptyChildren<TRow>(children: TRow[] | undefined): children is TRow[] {
  return !!children && children.length > 0;
}

function buildExpansionRenderRows<TRow>(
  rows: TRow[],
  trackBy: TrackByFn<TRow>,
  expandedRows: Set<RowId>,
  childrenAccessor: (row: TRow) => TRow[] | undefined,
  isExpandable: (row: TRow) => boolean,
  depth = 0
): Omit<RenderRow<TRow>, 'index'>[] {
  return rows.flatMap((row) => {
    const id = trackBy(row);
    const children = childrenAccessor(row);
    const hasChildren = isExpandable(row);
    const isExpanded = expandedRows.has(id);
    const self: Omit<RenderRow<TRow>, 'index'> = {
      id,
      depth,
      kind: 'row',
      data: row,
      hasChildren,
      isExpanded,
    };
    const nested = hasNonEmptyChildren(children) && isExpanded
      ? buildExpansionRenderRows(children, trackBy, expandedRows, childrenAccessor, isExpandable, depth + 1)
      : [];
    return [self, ...nested];
  });
}

// Recursively collects the id of every expandable row, at any depth — used by `expandAll()`
// to seed `expandedRows`. Only recurses into rows whose children are already loaded; rows
// with lazy/unloaded children still get expanded (and their `rowExpanded` event fires), but
// their own descendants can't be discovered until fetched.
function collectExpandableRowIds<TRow>(
  rows: TRow[],
  trackBy: TrackByFn<TRow>,
  childrenAccessor: (row: TRow) => TRow[] | undefined,
  isExpandable: (row: TRow) => boolean
): RowId[] {
  return rows.flatMap((row) => {
    if (!isExpandable(row)) {
      return [];
    }
    const children = childrenAccessor(row);
    const nested = hasNonEmptyChildren(children)
      ? collectExpandableRowIds(children, trackBy, childrenAccessor, isExpandable)
      : [];
    return [trackBy(row), ...nested];
  });
}

/**
 * Adds multi-expand, tree-capable row expansion to a `createTable()`. Standalone — reads
 * only core members, no dependency on any other feature. Declares `renderRows` to flatten
 * expanded children into `renderRows()` (see with-expansion.md), so it cannot be composed
 * alongside another feature that does the same.
 */
export function withExpansion<TRow = unknown>(config: WithExpansionConfig<TRow> = {}) {
  const childrenAccessor = config.childrenAccessor ?? defaultChildrenAccessor<TRow>;
  const isExpandable =
    config.isExpandable ?? ((row: TRow) => hasNonEmptyChildren(childrenAccessor(row)));

  return (
    core: ExpansionInput<TRow>
  ): TableFeatureSpec<TRow, ExpansionMembers> => {
    const expandedRows = signal(new Set<RowId>());
    const everExpanded = signal(new Set<RowId>());
    const rowExpandedSource = new Subject<RowId>();

    function toggleExpanded(rowId: RowId): void {
      const next = new Set(expandedRows());
      const isCollapsing = next.has(rowId);
      if (isCollapsing) {
        next.delete(rowId);
      } else {
        next.add(rowId);
        everExpanded.update((seen) => new Set(seen).add(rowId));
      }
      expandedRows.set(next);
      rowExpandedSource.next(rowId);
    }

    function expandAll(): void {
      const ids = collectExpandableRowIds(
        core.rows(),
        core.trackBy,
        childrenAccessor,
        isExpandable
      );
      everExpanded.update((seen) => {
        const next = new Set(seen);
        ids.forEach((id) => next.add(id));
        return next;
      });
      expandedRows.set(new Set(ids));
    }

    function collapseAll(): void {
      expandedRows.set(new Set());
    }

    // ADR-0006: `expandedRows` answers "is this row live and expanded" — an id that leaves
    // `data` must leave here too. `everExpanded` answers "has this id ever been expanded" and
    // is deliberately exempt (see its member doc).
    function onRowsRemoved(ids: readonly RowId[]): void {
      const next = pruneByIds(expandedRows(), ids);
      if (next !== expandedRows()) {
        expandedRows.set(new Set(next));
      }
    }

    return {
      members: {
        expandedRows: expandedRows.asReadonly(),
        everExpanded: everExpanded.asReadonly(),
        rowExpanded: rowExpandedSource.asObservable(),
        toggleExpanded,
        expandAll,
        collapseAll,
      },
      renderRows: (rows) =>
        buildExpansionRenderRows(
          rows,
          core.trackBy,
          expandedRows(),
          childrenAccessor,
          isExpandable
        ),
      onRowsRemoved,
    };
  };
}

import { computed, DestroyRef, effect, inject } from '@angular/core';
import type { AnyTableFeature, RowId, TableStore } from '../api/types';
import { createTableCore, type TableCoreHandle } from './core';
import { PIPELINE_ORDER } from './pipeline';
import { diffRemovedIds } from './rows';
import { describeFeature, SlotRegistry } from './slots';
import type { TableCore, TableEngineConfig, TableFeatureSpec } from './types';

interface FeatureHooks {
  readonly onInit: (() => void)[];
  readonly onDestroy: (() => void)[];
  readonly onRowsRemoved: ((ids: readonly RowId[]) => void)[];
}

/**
 * Calls every feature factory in array order, registering what each one declares. Members are
 * merged into `composed` as they arrive, which is what makes the feature-to-feature seam
 * order-dependent at factory time and complete afterwards.
 */
function foldFeatures<TRow>(
  features: readonly AnyTableFeature[],
  core: TableCore<TRow>,
  composed: Record<string, unknown>,
  handle: TableCoreHandle<TRow>
): FeatureHooks {
  const registry = new SlotRegistry();
  const hooks: FeatureHooks = { onInit: [], onDestroy: [], onRowsRemoved: [] };

  features.forEach((feature, index) => {
    const spec: TableFeatureSpec<TRow> = feature(core, composed);
    const label = describeFeature(index);

    if (spec.stages) {
      for (const stage of PIPELINE_ORDER) {
        const transform = spec.stages[stage];
        if (!transform) {
          continue;
        }
        registry.claimStage(stage, label);
        handle.stages[stage] = transform;
      }
    }

    if (spec.renderRows) {
      registry.claimRenderRows(label);
      handle.setRenderRowsBuilder(spec.renderRows);
    }

    Object.assign(composed, spec.members);

    if (spec.columnRules) {
      handle.columnRules.push(...spec.columnRules);
    }

    if (spec.onInit) {
      hooks.onInit.push(spec.onInit);
    }
    if (spec.onDestroy) {
      hooks.onDestroy.push(spec.onDestroy);
    }
    if (spec.onRowsRemoved) {
      hooks.onRowsRemoved.push(spec.onRowsRemoved);
    }
  });

  return hooks;
}

/**
 * Composes the table's state layer from a core config plus an ordered feature list, and
 * returns a live store **instance** — no class, no DI token. Features declare what they
 * contribute (`members`, `stages`, `renderRows`, hooks); this function is the only place
 * that wires those declarations together.
 *
 * Must run inside an Angular injection context: `onInit` hooks create `effect()` /
 * `resource()`, and `onDestroy` hooks register on the ambient `DestroyRef`.
 */
export function composeTable<TRow>(
  config: TableEngineConfig<TRow>,
  features: readonly AnyTableFeature[]
): TableStore<TRow> {
  const handle = createTableCore<TRow>(config);

  // Stable reference — features that read it at factory time see only earlier features,
  // features that read it from a method or computed see everything.
  const composed: Record<string, unknown> = {};
  const hooks = foldFeatures(features, handle.core, composed, handle);

  // ADR-0005: default is the row count before any virtualization/pagination trims what's
  // actually rendered — equals `renderRows().length` until a future feature overrides it.
  const totalRowCount = computed(() => handle.core.rows().length);

  const store = Object.assign(
    { ...handle.core, renderRows: handle.renderRows, totalRowCount },
    composed
  );

  // Hooks run only once every feature is composed, so an `onInit` can read any other
  // feature's members.
  for (const onInit of hooks.onInit) {
    onInit();
  }
  if (hooks.onDestroy.length > 0) {
    const destroyRef = inject(DestroyRef);
    for (const onDestroy of hooks.onDestroy) {
      destroyRef.onDestroy(onDestroy);
    }
  }

  // ADR-0006: reconciles feature state (expanded rows, open edits, ...) against `data`. An
  // effect, not a hook inside `updateRows` — a full `data.set(...)` replacement (paging,
  // refetch, a WebSocket snapshot) never passes through `core.value.update(...)`, so a
  // write-site hook would miss exactly the case where every id is orphaned at once. Seeding
  // `previousIds` before the effect exists means its first run diffs against itself instead of
  // reporting every row as removed at construction.
  if (hooks.onRowsRemoved.length > 0) {
    let previousIds = new Set(handle.core.indexById().keys());
    effect(() => {
      const currentIds = new Set(handle.core.indexById().keys());
      const removed = diffRemovedIds(previousIds, currentIds);
      previousIds = currentIds;
      if (removed.length > 0) {
        for (const onRowsRemoved of hooks.onRowsRemoved) {
          onRowsRemoved(removed);
        }
      }
    });
  }

  // The one seam where static typing gives way to dynamic composition: `composed` is
  // built by folding a runtime-length feature array. `createTable()` reconstructs the
  // full member type independently via `ComposedFeatureMembers<Features>`.
  return store;
}

import type { ResourceRef, Signal } from '@angular/core';
import type { ColumnDef } from './types';

/**
 * Read-only reactive context handed to a rule's `when`/`params` callback.
 * Minimal by design (Tier 1 only needs the current resolved columns) —
 * mirrors how `with-sorting.ts` reads `store.columns()`.
 *
 * Resolves to `baseColumns`, never the derived `columns` — rules observe declared and
 * imperatively-updated column state, never another rule's own output. Reading `columns`
 * here would close the `columns → ruleResults → params → resource → ruleResults` cycle (D8).
 */
export interface ColumnRuleContext<TRow> {
  readonly columns: () => ColumnDef<TRow>[];
}

/** @internal */
export const COLUMN_RECORDER: unique symbol = Symbol('COLUMN_RECORDER');

/**
 * Internal recorder every `apply*` call writes into. One instance per
 * `columnSchema()` / inline-fn execution — collects rules for later
 * resolution by `resolveColumnsConfig()`.
 * @internal
 */
export interface ColumnSchemaRecorder<TRow> {
  record(rule: ColumnRule<TRow>): void;
}

/**
 * Structural proxy mirroring Signal Forms' `FieldPathNode` — the `get` trap
 * fabricates a `ColumnHandle<TRow, K>` for any string property accessed. It
 * does not read actual column data; typing is 100% compile-time.
 */
export type ColumnsPath<TRow> = {
  readonly [K in Extract<keyof TRow, string>]: ColumnHandle<TRow, K>;
};

export interface ColumnHandle<
  TRow,
  K extends Extract<keyof TRow, string> = Extract<keyof TRow, string>
> {
  readonly id: K;
  /** @internal */
  readonly [COLUMN_RECORDER]: ColumnSchemaRecorder<TRow>;
}

export type ColumnsSchemaFn<TRow> = (path: ColumnsPath<TRow>) => void;

/** Opaque, compiled form of a schema fn — the standalone-reuse value. */
export interface ColumnSchema<TRow> {
  readonly kind: 'column-schema';
  readonly rules: readonly ColumnRule<TRow>[];
}

/**
 * Unique typed key for a consumer-registered column metadata entry. Object identity is the
 * actual key — `_type` is a phantom, never-assigned carrier so `T` flows through
 * `metadata()`/`readColumnMeta()` at compile time only. Mirrors Signal Forms'
 * `createMetadataKey()`.
 */
export interface ColumnMetaKey<T> {
  readonly kind: 'column-meta-key';
  /** @internal phantom type carrier — never assigned, compile-time only */
  readonly _type?: T;
}

/**
 * Consumer-defined side-channel data attached to a column, plus the internal shape
 * `applyVisible()` (`api/column-rules.ts`) records under the unexported `VISIBLE` key
 * (`engine/columns.ts`) — both go through the same recorder/resolve/wiring/fold path.
 * `logic` is either a plain value or a closure over `ColumnRuleContext<TRow>`, discriminated
 * at wiring time. Single-writer only for consumer keys: `resolve.ts` throws if two
 * `metadata()` calls target the same `(columnId, key)` pair — no reducer/combine story there
 * (see `docs/2-columns/reference/column-metadata.md`). `VISIBLE` is exempted from that check
 * since multiple `applyVisible()` calls on one column AND-combine (`engine/columns.ts`'s
 * `foldColumnRules`), mirroring Signal Forms' constraint-validator reducers.
 */
export interface MetadataRule<TRow, T = unknown> {
  readonly kind: 'metadata';
  readonly columnId: string;
  readonly key: ColumnMetaKey<T>;
  readonly logic: T | ((ctx: ColumnRuleContext<TRow>) => T);
}

/**
 * Resource-backed counterpart to `MetadataRule`, generalized from the old `visible-async`
 * shape to carry an arbitrary `key` — used internally by `applyVisibleAsync()`
 * (`api/column-rules.ts`) to write to `VISIBLE`. Not part of the public `metadata()` surface
 * (no async story there yet); kept as its own rule kind because resource construction
 * (`factory(params)`) must happen once at wiring time, not on every fold, so it can't be
 * expressed as `MetadataRule`'s plain-value-or-closure `logic`.
 */
export interface MetadataAsyncRule<TRow, TParams = unknown, TResult = unknown, T = unknown> {
  readonly kind: 'metadata-async';
  readonly columnId: string;
  readonly key: ColumnMetaKey<T>;
  readonly params: (ctx: ColumnRuleContext<TRow>) => TParams | undefined;
  readonly factory: (
    params: Signal<TParams | undefined>
  ) => ResourceRef<TResult | undefined>;
  readonly onSuccess: (result: TResult) => T;
  readonly onError: (error: unknown) => T;
}

export type ColumnRule<TRow> = MetadataRule<TRow> | MetadataAsyncRule<TRow>;

