  { id: 1, name: 'Ada' },
  { id: 2, name: 'Bea' },
  { id: 3, name: 'Cid' },
];

export const mockTrackBy: TrackByFn<MockRow> = (row) => row.id;

/**
 * Minimal store stub carrying a real writable `value` view, for testing updater factories
 * through `table.value.update(...)` (D30) — not a full `composeTable()` instance.
 */
export function createMockTableStoreWithData<TRow>(
  rows: TRow[],
  trackBy: TrackByFn<TRow>
): TableStore<TRow> {
  const data = signal<TRow[]>(rows);
  return {
    columns: createWritableView<ColumnDef<TRow>[], never>(() => [], () => undefined),
    rows: signal<TRow[]>(rows),
    renderRows: signal<RenderRow<TRow>[]>([]),
    totalRowCount: signal(rows.length),
    trackBy,
    value: createWritableView<TRow[], RowUpdater<TRow>>(
      () => data(),
      (updater) => data.update((current) => updater(current, { trackBy }))
    ),
  };
}

/**
 * Minimal store stub carrying a writable `value` view plus a standalone `editing` view (not
 * wired through `withRowEdit()`/`composeTable()`) — for testing `row-edit-mutations.ts`
 * updater factories through `table.value`/`table.editing` in isolation.
 */
export function createMockTableStoreWithEditing<TRow>(
  rows: TRow[],
  trackBy: TrackByFn<TRow>
): TableStore<TRow> & RowEditMembers<TRow> {
  const data = signal<TRow[]>(rows);
  const state = signal<EditingState<TRow>>({ snapshots: new Map(), open: new Set() });
  const value = createWritableView<TRow[], RowUpdater<TRow>>(
    () => data(),
    (updater) => data.update((current) => updater(current, { trackBy }))
  );
  return {
    columns: createWritableView<ColumnDef<TRow>[], never>(() => [], () => undefined),
    rows: signal<TRow[]>(rows),
    renderRows: signal<RenderRow<TRow>[]>([]),
    totalRowCount: signal(rows.length),
    trackBy,
    value,
    editing: createWritableView<ReadonlySet<RowId>, EditingUpdater<TRow>>(
      () => state().open,
      (updater) =>
        state.set(
          updater(state(), {
            data: data(),
            trackBy,
            writeData: (rows) => value.update(() => rows),
          })
        )
    ),
    // Same derivation the feature uses, imported rather than restated — this stub deliberately
    // skips `withRowEdit()`'s single-mode trim, but `pending` must not drift from it.
    pending: computed(() => pendingIds(state())),
  };
}

import {
  Directive,
  effect,
  inject,
  input,
  TemplateRef,
  ViewContainerRef,
  type EmbeddedViewRef,
  type InputSignal,
} from '@angular/core';
import type { FieldTree } from '@angular/forms/signals';

import { resolveRowField } from './ngp-table-row-field.resolve';
import type { RenderRow } from '../api/types';

export interface NgpTableRowFieldContext<TRow> {
  // Not readonly: the directive mutates these in place on `sourceIndex` change instead of
  // recreating the embedded view (matches `NgIfContext`'s own mutable-field pattern).
  $implicit: FieldTree<TRow>;
  ngpTableRowField: FieldTree<TRow>;
}

/**
 * Structural directive folding the E2 pattern —
 * `@if (row.sourceIndex !== undefined) { @let field = rows[row.sourceIndex]; }` — into one
 * template line. See D33, `docs/1-state/work/with-row-editing/2-decisions.md`, for why this
 * lives behind the `@acme/table/forms` secondary entry point rather than the root barrel.
 */
@Directive({ selector: '[ngpTableRowField]' })
export class NgpTableRowFieldDirective<TRow> {
  private readonly templateRef =
    inject<TemplateRef<NgpTableRowFieldContext<TRow>>>(TemplateRef);
  private readonly viewContainerRef = inject(ViewContainerRef);

  private viewRef: EmbeddedViewRef<NgpTableRowFieldContext<TRow>> | null = null;

  readonly ngpTableRowField: InputSignal<RenderRow<TRow>> = input.required<RenderRow<TRow>>();
  readonly ngpTableRowFieldFrom: InputSignal<FieldTree<TRow[]>> =
    input.required<FieldTree<TRow[]>>();

  static ngTemplateContextGuard<TRow>(
    _dir: NgpTableRowFieldDirective<TRow>,
    _ctx: unknown
  ): _ctx is NgpTableRowFieldContext<TRow> {
    return true;
  }

  constructor() {
    effect(() => {
      const field = resolveRowField(this.ngpTableRowFieldFrom(), this.ngpTableRowField());
      if (field === undefined) {
        this.viewRef = null;
        this.viewContainerRef.clear();
        return;
      }
      if (this.viewRef === null) {
        this.viewRef = this.viewContainerRef.createEmbeddedView(this.templateRef, {
          $implicit: field,
          ngpTableRowField: field,
        });
        return;
      }
      this.viewRef.context.$implicit = field;
      this.viewRef.context.ngpTableRowField = field;
    });
  }
}

import type { Signal, WritableSignal } from '@angular/core';
import type { ColumnMetaKey, ColumnSchema, ColumnsSchemaFn } from './column-schema.types';
import type { TableFeature } from '../engine/types';
import type { WritableView } from '../engine/writable-view';

export type RowId = string | number;

/**
 * Reactive row-data source handed to `createTable(data, ...)`. The consumer's
 * `WritableSignal<TRow[]>` is the single source of truth (D3/D4) — the pipeline reads it
 * directly via `computed()`, there is no internal copy to fall out of sync.
 */
export type TableDataInput<TRow> = WritableSignal<TRow[]>;

export type SortDirection = 'asc' | 'desc';

export interface SortRule {
  columnId: string;
  direction: SortDirection;
}

export type TrackByFn<TRow> = (row: TRow) => RowId;

export type TrackByConfig<TRow> = keyof TRow | TrackByFn<TRow>;

/**
 * Render-layer row: `rows()`'s pipeline output flattened for template/virtual-scroll
 * consumption. `kind: 'group'` rows are synthetic — no `TRow` backs them, hence `data:
 * null` — introduced by `withGrouping()`'s `_buildRenderRows` override.
 */
export type RowKind = 'row' | 'group';

export interface RenderRow<TRow> {
  readonly id: RowId;

  // `depth` is 0 for a normal `kind: 'row'`, and increments for each level of nesting.
  readonly depth: number;
  readonly kind: RowKind;
  readonly data: TRow | null;

  // Position in the final `renderRows()` array, assigned centrally after any feature's
  // `renderRows` builder runs (`engine/core.ts`) — never set by a builder itself. Feeds
  // `aria-rowindex` on `ngpTableRow` (ADR-0005), since a `<div>`-hosted grid loses the free
  // DOM-order inference native `<table>` gives for free.
  readonly index: number;

  // `aggregates` holds data for a `group` row's template, e.g. output of `withAggregation()`.
  readonly aggregates?: Record<string, unknown>;

  // Set only when `withExpansion()` is composed.
  readonly isExpanded?: boolean;

  // `hasChildren` is true for a `group` row that has at least one child.
  readonly hasChildren?: boolean;

  // Index into `data()` for the `TRow` this render row was built from, resolved by trackBy
  // id (`engine/core.ts`). `undefined` for synthesized rows (`kind: 'group'`, or any row a
  // feature's `renderRows` builder fabricates) — there is no `data()` entry to point to.
  readonly sourceIndex?: number;
}

export interface ColumnDef<TRow = unknown> {
  id: string;
  accessor: (row: TRow) => unknown;
  visible: boolean;
  order: number;
  label: string;

  // Feature-contributed fields, populated when the corresponding feature is registered.
  sortFn?: (a: TRow, b: TRow) => number;
  enableSorting?: boolean;
  aggregateFn?: (rows: TRow[]) => unknown;
  filterFn?: (value: unknown, filterValue: unknown) => boolean;
  enableFiltering?: boolean;

  // Consumer-registered side-channel data, keyed by `ColumnMetaKey<T>` identity — never
  // interpreted by the engine. Read via `readColumnMeta()`, written via `metadata()`
  // (`api/column-metadata.ts`).
  meta?: ReadonlyMap<ColumnMetaKey<unknown>, unknown>;
}

/**
 * Author-facing column shape, accepted by `createTable()`'s `columns` config and
 * `setColumns()`. `accessor`/`visible`/`order`/`label` are optional here and resolved to a
 * full `ColumnDef` at store construction — `accessor` defaults to `(row) => row[id]`,
 * `visible` defaults to `true`, `order` defaults to the column's index in the array,
 * `label` defaults to `id`. Only `id` is required. The resolved store state
 * (`store.columns()`) is always a full `ColumnDef[]`.
 */
export type ColumnDefInput<TRow = unknown> = Pick<ColumnDef<TRow>, 'id'> &
  Partial<Omit<ColumnDef<TRow>, 'id'>>;

// Opaque handle for a `createTable()` feature (`withSorting()`, `withGrouping()`, etc.) —
// consumers never construct this by hand, it's the return type of the feature functions
// the design system exports.
//
// Consequence: consumers must repeat `<TRow>` on every feature call
// (`withExpansion<Department>()`), since a feature is called before it receives the store,
// so its call site has no argument to infer from. The fix — `features: (t) => [...]`, where
// each feature takes the core as an argument — became possible once `@ngrx/signals` was
// dropped, and is deliberately deferred. See ADR-0003 and `docs/1-state/architecture.md`,
// "Rejected: inferring TRow into with-*() calls".
export type AnyTableFeature = TableFeature<any, any>;

export interface TableStoreConfig<
  TRow,
  Features extends readonly AnyTableFeature[] = []
> {
  trackBy: TrackByConfig<TRow>;
  columns: ColumnDefInput<TRow>[];
  columnsSchema?: ColumnsSchemaFn<TRow> | ColumnSchema<TRow>;
  features?: Features;
}

// Distributes a union of feature outputs into an intersection, so composing N features
// surfaces the union of everything each one contributes as a single flat type. Computed
// independently of the runtime fold, because `createTable()` folds a dynamic-length
// `features` array rather than passing them positionally.
type UnionToIntersection<Union> = (
  Union extends unknown ? (member: Union) => void : never
) extends (member: infer Intersection) => void
  ? Intersection
  : never;

// `members` is optional on `TableFeatureSpec`, so it must be inferred through an optional
// property and un-widened — a feature contributing none (e.g. one that only wires an
// `onInit`) yields `object`, which is inert inside the intersection below.
type FeatureMembers<Feature> = Feature extends (...args: any[]) => infer Spec
  ? Spec extends { members?: infer Members }
    ? NonNullable<Members>
    : object
  : never;

export type ComposedFeatureMembers<Features extends readonly AnyTableFeature[]> =
  UnionToIntersection<FeatureMembers<Features[number]>>;

/**
 * Public surface of a store returned by `createTable()`. This is the contract consumers
 * program against — it never references engine types, so swapping the internal
 * state-management implementation is not a breaking change. Validated 2026-08-11: the
 * `@ngrx/signals` → `composeTable()` swap landed with zero consumer diff (ADR-0003).
 */
export type ColumnsUpdater<TRow> = (
  columns: ColumnDef<TRow>[]
) => ColumnDef<TRow>[];

/**
 * Pure row transform. `ctx.trackBy` is supplied by `table.value.update(...)` (D30) so
 * id-based updaters (`removeRow`, `patchRow`) can resolve identity without needing a store
 * reference themselves — this is what keeps them tree-shakeable and unit-testable standalone
 * (D6). The raw-lambda form `rows => rows.filter(...)` satisfies this type too; it just
 * ignores `ctx`.
 */
export type RowUpdater<TRow> = (
  rows: TRow[],
  ctx: { trackBy: TrackByFn<TRow> }
) => TRow[];

export interface TableStore<TRow> {
  /** Read: the folded, rule-applied column list. Write: `.update(updater)` (D30) — e.g.
   * `table.columns.update(reorderColumns(ids))`. */
  readonly columns: WritableView<ColumnDef<TRow>[], ColumnsUpdater<TRow>>;
  readonly rows: Signal<TRow[]>;
  readonly renderRows: Signal<RenderRow<TRow>[]>;
  readonly trackBy: TrackByFn<TRow>;

  // Total row count feeding `aria-rowcount` on `ngpTable` (ADR-0005) — distinct from
  // `renderRows().length` once virtualization/pagination renders fewer rows than exist.
  // Equals `rows().length` until a virtualization feature overrides it.
  readonly totalRowCount: Signal<number>;

  /** Read: the row data (D3/D4 — the consumer's own signal, single source of truth). Write:
   * `.update(updater)` (D30) — e.g. `table.value.update(addRow(row, { at: 0 }))`. */
  readonly value: WritableView<TRow[], RowUpdater<TRow>>;
}

import { computed, signal, type Signal } from '@angular/core';
import { pruneByIds } from '../../engine/rows';
import type { TableCore, TableFeatureSpec } from '../../engine/types';
import { createWritableView, type WritableView } from '../../engine/writable-view';
import type { EditingState, EditingUpdater } from '../row-edit-mutations';
import type { RowId } from '../types';

/** Sentinel snapshot value: the row did not exist in `data` when `beginEdit` captured it
 * (D28) — the blank-row-add flow. `revertEdit` reads this to remove the row instead of
 * restoring a value. */
export const ABSENT = Symbol('row-edit-absent');

export type RowSnapshot<TRow> = TRow | typeof ABSENT;

/** id -> the row's value at the moment `beginEdit` first captured it (D17), or `ABSENT` (D28).
 * One restore point per row; whether that row is currently open is a separate fact. */
export type SnapshotMap<TRow> = ReadonlyMap<RowId, RowSnapshot<TRow>>;

export interface WithRowEditConfig {
  /** Default `false` (D14): a second `beginEdit` closes whatever row was already open. */
  multiple?: boolean;
}

export interface RowEditMembers<TRow> {
  /** Read: which rows are open for editing. Write: `.update(updater)` (D30) — e.g.
   * `table.editing.update(beginEdit(id))`. Every updater, including the ones that only touch
   * restore points, is applied through this one view. */
  readonly editing: WritableView<ReadonlySet<RowId>, EditingUpdater<TRow>>;
  /** D31: rows closed by `endEdit(id, { keepSnapshot: true })` — visually done, still
   * rollback-able while an optimistic save is in flight. Derived from the state, so a row can
   * never be open and pending at once. */
  readonly pending: Signal<ReadonlySet<RowId>>;
}

const NO_IDS: ReadonlySet<RowId> = new Set();

/**
 * D31: holds a restore point but is no longer open. Derived rather than stored — this is what
 * makes `endEdit`'s "move to pending" a single `open.delete(id)` with no second container to
 * fall out of step with (D31.5).
 */
export function pendingIds<TRow>(state: EditingState<TRow>): ReadonlySet<RowId> {
  const ids = new Set<RowId>();
  for (const id of state.snapshots.keys()) {
    if (!state.open.has(id)) {
      ids.add(id);
    }
  }
  // Shared empty set so the common case (nothing pending) keeps a stable identity and does not
  // invalidate downstream computeds on every open/close. Checked after the scan, not before:
  // a size comparison would depend on `open ⊆ snapshots` holding, and would return a silently
  // wrong answer rather than fail if it ever stopped.
  return ids.size === 0 ? NO_IDS : ids;
}

/**
 * Single mode (D14): keeps only the most recently opened row. The rows it displaces are closed
 * the way `endEdit` does — their restore points go with them, since under D24 whatever the user
 * typed was already committed on blur and keeping it is the unsurprising outcome (D31.2).
 */
function closeAllButLast<TRow>(state: EditingState<TRow>): EditingState<TRow> {
  const ids = [...state.open];
  const snapshots = new Map(state.snapshots);
  for (const displaced of ids.slice(0, -1)) {
    snapshots.delete(displaced);
  }
  return { snapshots, open: new Set(ids.slice(-1)) };
}

/**
 * Adds button-triggered edit-mode tracking (F2b) to a `createTable()` — which rows are
 * currently open for editing, plus their pre-edit restore points for `revertEdit` (D17/D28).
 * Mode gate only: claims no pipeline stage and no `renderRows` slot (D10, `4-increments.md`
 * E3). The consumer's own `form(data)` (D22) owns the actual field values; this feature only
 * tracks which rows show the form's inputs.
 *
 * `{ multiple: true }` combined with optimistic save (D31) is undesigned — N open rows × M
 * in-flight saves — and unsupported until someone specs it (D31.2).
 */
export function withRowEdit<TRow = unknown>(config: WithRowEditConfig = {}) {
  const multiple = config.multiple ?? false;

  return (core: TableCore<TRow>): TableFeatureSpec<TRow, RowEditMembers<TRow>> => {
    // One signal over both facts: `pending` is derived from them together, so it can never
    // read a half-applied write (D31.5).
    const state = signal<EditingState<TRow>>({ snapshots: new Map(), open: new Set() });

    // Enforces D14's single-mode "closes whatever was open" without any updater (beginEdit,
    // etc.) needing to know about `multiple` — every write funnels through here.
    function applyEditingState(next: EditingState<TRow>): void {
      const exceedsSingleMode = !multiple && next.open.size > 1;
      state.set(exceedsSingleMode ? closeAllButLast(next) : next);
    }

    const members = {
      editing: createWritableView<ReadonlySet<RowId>, EditingUpdater<TRow>>(
        () => state().open,
        (updater) =>
          applyEditingState(
            updater(state(), {
              data: core.value(),
              trackBy: core.trackBy,
              writeData: (rows) => core.value.update(() => rows),
            })
          )
      ),
      pending: computed(() => pendingIds(state())),
    };

    // ADR-0006: an id that leaves `data` must leave both `open` (nothing left to show inputs
    // for) and `snapshots` (nothing left to restore) — `pending` needs no pruning of its own,
    // since it is derived from the other two, not stored. `open` is pruned independently of
    // `snapshots`: `pendingIds()` treats "has a snapshot but isn't open" as pending, so leaving
    // a removed id in `open` would surface it as newly pending. `ABSENT` snapshots (D28) are
    // exempt — they were never backed by a row in `data` to begin with.
    function onRowsRemoved(ids: readonly RowId[]): void {
      const current = state();
      const nextOpen = pruneByIds(current.open, ids);
      const nextSnapshots = pruneByIds(current.snapshots, ids, (value) => value === ABSENT);
      if (nextOpen !== current.open || nextSnapshots !== current.snapshots) {
        applyEditingState({ open: nextOpen, snapshots: nextSnapshots });
      }
    }

    return { members, onRowsRemoved } as TableFeatureSpec<TRow, RowEditMembers<TRow>>;
  };
}

import { computed, signal, type Signal } from '@angular/core';
import { Subject, type Observable } from 'rxjs';
import type { TableCore, TableFeatureSpec } from '../../engine/types';
import type { ColumnDef, SortDirection, SortRule } from '../types';

export interface WithSortingConfig {
  manual?: boolean;
  multi?: boolean;
}

/** The slice of the core store this feature reads. */
type SortingInput<TRow> = Pick<TableCore<TRow>, 'columns'>;

export interface SortingMembers {
  readonly sorting: Signal<SortRule[]>;
  readonly sortDirections: Signal<ReadonlyMap<string, SortDirection>>;
  readonly sortChanged: Observable<SortRule[]>;

  toggleSort(columnId: string): void;
  setSorting(rules: SortRule[]): void;
  clearSorting(): void;
}

function toSortDirectionsMap(rules: SortRule[]): ReadonlyMap<string, SortDirection> {
  const directions = new Map<string, SortDirection>();
  for (const rule of rules) {
    directions.set(rule.columnId, rule.direction);
  }
  return directions;
}

function cycleSortRule(rules: SortRule[], columnId: string): SortRule[] {
  const index = rules.findIndex((rule) => rule.columnId === columnId);
  if (index === -1) {
    return [...rules, { columnId, direction: 'asc' }];
  }
  if (rules[index].direction === 'asc') {
    return rules.map((rule, i) =>
      i === index ? { ...rule, direction: 'desc' as const } : rule
    );
  }
  return rules.filter((_, i) => i !== index);
}

function replaceSortRule(rules: SortRule[], columnId: string): SortRule[] {
  const current = rules[0];
  if (!current || current.columnId !== columnId) {
    return [{ columnId, direction: 'asc' }];
  }
  if (current.direction === 'asc') {
    return [{ columnId, direction: 'desc' }];
  }
  return [];
}

function detectComparator<TRow>(
  accessor: (row: TRow) => unknown,
  rows: TRow[]
): (a: TRow, b: TRow) => number {
  const sample = rows.map(accessor).find((value) => value != null);
  if (sample instanceof Date) {
    return (a, b) =>
      (accessor(a) as Date).getTime() - (accessor(b) as Date).getTime();
  }
  if (typeof sample === 'number') {
    return (a, b) => (accessor(a) as number) - (accessor(b) as number);
  }
  // String(), not `.toString()` on the raw value — the spec's fallback is
  // locale string compare via `.toString()`, but individual rows can still hold
  // null/undefined even when the detection sample above found a non-null value
  // elsewhere in the column; String() handles that without throwing.
  return (a, b) =>
    String(accessor(a)).localeCompare(String(accessor(b)));
}

function sortRows<TRow>(
  rows: TRow[],
  rules: SortRule[],
  columns: ColumnDef<TRow>[]
): TRow[] {
  if (rules.length === 0) {
    return rows;
  }
  const columnById = new Map(columns.map((column) => [column.id, column]));
  const comparators = rules.flatMap((rule) => {
    const column = columnById.get(rule.columnId);
    if (!column) {
      return [];
    }
    const compare = column.sortFn ?? detectComparator(column.accessor, rows);
    const sign = rule.direction === 'asc' ? 1 : -1;
    return [(a: TRow, b: TRow) => sign * compare(a, b)];
  });

  return [...rows].sort((a, b) => {
    for (const compare of comparators) {
      const result = compare(a, b);
      if (result !== 0) {
        return result;
      }
    }
    return 0;
  });
}

/**
 * Adds three-state (ascending -> descending -> unsorted) sorting to a
 * `createTable()`. Reads `sortFn` / `enableSorting` directly off the core
 * `columns` config — no compile-time feature dependency (see with-sorting.md).
 *
 * By default (`multi: false`), clicking a column replaces the sort with that
 * column alone. Pass `{ multi: true }` to accumulate a click-ordered,
 * multi-column priority sort instead.
 */
export function withSorting<TRow = unknown>(config: WithSortingConfig = {}) {
  const manual = config.manual ?? false;
  const multi = config.multi ?? false;

  return (core: SortingInput<TRow>): TableFeatureSpec<TRow, SortingMembers> => {
    const sorting = signal<SortRule[]>([]);
    const sortDirections = computed(() => toSortDirectionsMap(sorting()));
    const sortChangedSource = new Subject<SortRule[]>();

    function applySorting(rules: SortRule[]): void {
      sorting.set(rules);
      sortChangedSource.next(rules);
    }

    function toggleSort(columnId: string): void {
      const column = core.columns().find((c) => c.id === columnId);
      const isSortable = !!column && column.enableSorting !== false;
      if (!isSortable) {
        return;
      }
      applySorting(
        multi
          ? cycleSortRule(sorting(), columnId)
          : replaceSortRule(sorting(), columnId)
      );
    }

    return {
      members: {
        sorting: sorting.asReadonly(),
        sortDirections,
        sortChanged: sortChangedSource.asObservable(),
        toggleSort,
        setSorting: applySorting,
        clearSorting: () => applySorting([]),
      },
      stages: {
        sort: (rows) =>
          manual ? rows : sortRows(rows, sorting(), core.columns()),
      },
    };
  };
}

import type { Signal, WritableSignal } from '@angular/core';
import type { ColumnMetaKey, ColumnSchema, ColumnsSchemaFn } from './column-schema.types';
import type { TableFeature } from '../engine/types';
import type { WritableView } from '../engine/writable-view';

export type RowId = string | number;

/**
 * Reactive row-data source handed to `createTable(data, ...)`. The consumer's
 * `WritableSignal<TRow[]>` is the single source of truth (D3/D4) — the pipeline reads it
 * directly via `computed()`, there is no internal copy to fall out of sync.
 */
export type TableDataInput<TRow> = WritableSignal<TRow[]>;

export type SortDirection = 'asc' | 'desc';

export interface SortRule {
  columnId: string;
  direction: SortDirection;
}

export type TrackByFn<TRow> = (row: TRow) => RowId;

export type TrackByConfig<TRow> = keyof TRow | TrackByFn<TRow>;

/**
 * Render-layer row: `rows()`'s pipeline output flattened for template/virtual-scroll
 * consumption. `kind: 'group'` rows are synthetic — no `TRow` backs them, hence `data:
 * null` — introduced by `withGrouping()`'s `_buildRenderRows` override.
 */
export type RowKind = 'row' | 'group';

export interface RenderRow<TRow> {
  readonly id: RowId;

  // `depth` is 0 for a normal `kind: 'row'`, and increments for each level of nesting.
  readonly depth: number;
  readonly kind: RowKind;
  readonly data: TRow | null;

  // Position in the final `renderRows()` array, assigned centrally after any feature's
  // `renderRows` builder runs (`engine/core.ts`) — never set by a builder itself. Feeds
  // `aria-rowindex` on `ngpTableRow` (ADR-0005), since a `<div>`-hosted grid loses the free
  // DOM-order inference native `<table>` gives for free.
  readonly index: number;

  // `aggregates` holds data for a `group` row's template, e.g. output of `withAggregation()`.
  readonly aggregates?: Record<string, unknown>;

  // Set only when `withExpansion()` is composed.
  readonly isExpanded?: boolean;

  // `hasChildren` is true for a `group` row that has at least one child.
  readonly hasChildren?: boolean;

  // Index into `data()` for the `TRow` this render row was built from, resolved by trackBy
  // id (`engine/core.ts`). `undefined` for synthesized rows (`kind: 'group'`, or any row a
  // feature's `renderRows` builder fabricates) — there is no `data()` entry to point to.
  readonly sourceIndex?: number;
}

export interface ColumnDef<TRow = unknown> {
  id: string;
  accessor: (row: TRow) => unknown;
  visible: boolean;
  order: number;
  label: string;

  // Feature-contributed fields, populated when the corresponding feature is registered.
  sortFn?: (a: TRow, b: TRow) => number;
  enableSorting?: boolean;
  aggregateFn?: (rows: TRow[]) => unknown;
  filterFn?: (value: unknown, filterValue: unknown) => boolean;
  enableFiltering?: boolean;

  // Consumer-registered side-channel data, keyed by `ColumnMetaKey<T>` identity — never
  // interpreted by the engine. Read via `readColumnMeta()`, written via `metadata()`
  // (`api/column-metadata.ts`).
  meta?: ReadonlyMap<ColumnMetaKey<unknown>, unknown>;
}

/**
 * Author-facing column shape, accepted by `createTable()`'s `columns` config and
 * `setColumns()`. `accessor`/`visible`/`order`/`label` are optional here and resolved to a
 * full `ColumnDef` at store construction — `accessor` defaults to `(row) => row[id]`,
 * `visible` defaults to `true`, `order` defaults to the column's index in the array,
 * `label` defaults to `id`. Only `id` is required. The resolved store state
 * (`store.columns()`) is always a full `ColumnDef[]`.
 */
export type ColumnDefInput<TRow = unknown> = Pick<ColumnDef<TRow>, 'id'> &
  Partial<Omit<ColumnDef<TRow>, 'id'>>;

// Opaque handle for a `createTable()` feature (`withSorting()`, `withGrouping()`, etc.) —
// consumers never construct this by hand, it's the return type of the feature functions
// the design system exports.
//
// Consequence: consumers must repeat `<TRow>` on every feature call
// (`withExpansion<Department>()`), since a feature is called before it receives the store,
// so its call site has no argument to infer from. The fix — `features: (t) => [...]`, where
// each feature takes the core as an argument — became possible once `@ngrx/signals` was
// dropped, and is deliberately deferred. See ADR-0003 and `docs/1-state/architecture.md`,
// "Rejected: inferring TRow into with-*() calls".
export type AnyTableFeature = TableFeature<any, any>;

export interface TableStoreConfig<
  TRow,
  Features extends readonly AnyTableFeature[] = []
> {
  trackBy: TrackByConfig<TRow>;
  columns: ColumnDefInput<TRow>[];
  columnsSchema?: ColumnsSchemaFn<TRow> | ColumnSchema<TRow>;
  features?: Features;
}

// Distributes a union of feature outputs into an intersection, so composing N features
// surfaces the union of everything each one contributes as a single flat type. Computed
// independently of the runtime fold, because `createTable()` folds a dynamic-length
// `features` array rather than passing them positionally.
type UnionToIntersection<Union> = (
  Union extends unknown ? (member: Union) => void : never
) extends (member: infer Intersection) => void
  ? Intersection
  : never;

// `members` is optional on `TableFeatureSpec`, so it must be inferred through an optional
// property and un-widened — a feature contributing none (e.g. one that only wires an
// `onInit`) yields `object`, which is inert inside the intersection below.
type FeatureMembers<Feature> = Feature extends (...args: any[]) => infer Spec
  ? Spec extends { members?: infer Members }
    ? NonNullable<Members>
    : object
  : never;

export type ComposedFeatureMembers<Features extends readonly AnyTableFeature[]> =
  UnionToIntersection<FeatureMembers<Features[number]>>;

/**
 * Public surface of a store returned by `createTable()`. This is the contract consumers
 * program against — it never references engine types, so swapping the internal
 * state-management implementation is not a breaking change. Validated 2026-08-11: the
 * `@ngrx/signals` → `composeTable()` swap landed with zero consumer diff (ADR-0003).
 */
export type ColumnsUpdater<TRow> = (
  columns: ColumnDef<TRow>[]
) => ColumnDef<TRow>[];

/**
 * Pure row transform. `ctx.trackBy` is supplied by `table.value.update(...)` (D30) so
 * id-based updaters (`removeRow`, `patchRow`) can resolve identity without needing a store
 * reference themselves — this is what keeps them tree-shakeable and unit-testable standalone
 * (D6). The raw-lambda form `rows => rows.filter(...)` satisfies this type too; it just
 * ignores `ctx`.
 */
export type RowUpdater<TRow> = (
  rows: TRow[],
  ctx: { trackBy: TrackByFn<TRow> }
) => TRow[];

export interface TableStore<TRow> {
  /** Read: the folded, rule-applied column list. Write: `.update(updater)` (D30) — e.g.
   * `table.columns.update(reorderColumns(ids))`. */
  readonly columns: WritableView<ColumnDef<TRow>[], ColumnsUpdater<TRow>>;
  readonly rows: Signal<TRow[]>;
  readonly renderRows: Signal<RenderRow<TRow>[]>;
  readonly trackBy: TrackByFn<TRow>;

  // Total row count feeding `aria-rowcount` on `ngpTable` (ADR-0005) — distinct from
  // `renderRows().length` once virtualization/pagination renders fewer rows than exist.
  // Equals `rows().length` until a virtualization feature overrides it.
  readonly totalRowCount: Signal<number>;

  /** Read: the row data (D3/D4 — the consumer's own signal, single source of truth). Write:
   * `.update(updater)` (D30) — e.g. `table.value.update(addRow(row, { at: 0 }))`. */
  readonly value: WritableView<TRow[], RowUpdater<TRow>>;
}

import type { Signal } from '@angular/core';
import type {
  ColumnDef,
  ColumnDefInput,
  ColumnsUpdater,
  RowId,
  RowUpdater,
  TableDataInput,
  TrackByConfig,
  TrackByFn,
} from '../api/types';
import type { ColumnRuleRegistry } from './columns';
import type { PipelineStages, RenderRowsBuilder } from './pipeline';
import type { WritableView } from './writable-view';

/** Core config `composeTable()` needs. Resolved by `createTable()` from the public config. */
export interface TableEngineConfig<TRow> {
  columns: ColumnDefInput<TRow>[];
  trackBy: TrackByConfig<TRow>;
  data: TableDataInput<TRow>;
}

/**
 * The slice of the store every feature can read, handed to feature factories as their
 * first argument. Fixed and feature-independent — a feature that needs *another
 * feature's* members reads the second argument instead.
 *
 * `rows` is the pipeline output, safe to close over during composition: it is a lazy
 * `computed` that reads the stage registry at evaluation time, and the registry is
 * complete before any consumer can read it.
 */
export interface TableCore<TRow> {
  /** Read: the folded, rule-applied column list. Write: `.update(updater)` targets the
   * underlying `baseColumns` — never the fold itself (D30). */
  readonly columns: WritableView<ColumnDef<TRow>[], ColumnsUpdater<TRow>>;
  /**
   * Engine-internal only: the pre-fold declared columns `columns` overlays rules onto.
   * Read-only here — `with-columns-schema` rule wiring reads against this (not the folded
   * `columns`) to avoid a rule observing its own output. Never assigned to publicly on
   * `TableStore`; writes go through `TableCore.columns.update(...)`.
   */
  readonly baseColumns: Signal<ColumnDef<TRow>[]>;
  readonly rows: Signal<TRow[]>;
  readonly trackBy: TrackByFn<TRow>;
  /** Maps a row's trackBy id to its position in `data()`. Engine-internal only: not exposed on
   * `TableStore`. Feeds the removal-reconciliation effect (ADR-0006) so it can diff ids without
   * recomputing them a second time. */
  readonly indexById: Signal<ReadonlyMap<RowId, number>>;
  /** Read: the consumer's own row data (D3/D4 — table never copies it). Write:
   * `.update(updater)` writes through to that same signal, resolving `trackBy` internally
   * for id-based updaters (D30). */
  readonly value: WritableView<TRow[], RowUpdater<TRow>>;
}

/**
 * What a feature contributes. Features **declare** rather than mutate the store — the
 * return type is the whole contract, so a stage or render-row override can't be injected
 * by convention alone.
 */
export interface TableFeatureSpec<TRow, Members extends object = object> {
  /** Signals and methods merged onto the public store. */
  members?: Members;

  /**
   * Pure row transforms. The engine folds registered stages in the fixed order
   * `filter -> group -> sort -> expand`, never in `features` array order. Two features
   * claiming the same key is a composition error.
   */
  stages?: PipelineStages<TRow>;

  /** Builds `renderRows()` from the pipeline output. At most one feature may provide it. */
  renderRows?: RenderRowsBuilder<TRow>;

  /**
   * Rule entries this feature contributes to the `columns` fold (`foldColumnRules`). Additive
   * only — not claimed via `SlotRegistry`: two features contributing rules to the same column
   * both apply. Read by `composeTable()`'s `foldFeatures()` and concatenated onto the core's
   * `columnRules` registry.
   */
  columnRules?: ColumnRuleRegistry<TRow>;

  /** Runs after every feature is composed, inside the owner's injection context. */
  onInit?: () => void;
  onDestroy?: () => void;
  /** Called with ids that just left `data` (ADR-0006). A feature storing `RowId`-keyed state
   * declares this and prunes its own state — the engine never reaches into feature state
   * itself. Fires for every removal, including a full `data.set(...)` replacement. */
  onRowsRemoved?: (ids: readonly RowId[]) => void;
}

/**
 * A composed feature. `composed` is the feature-to-feature seam: a stable reference to
 * the accumulating member object. Read at factory time it holds only earlier features
 * (so `features` array order matters); read later — inside a method or computed — it
 * holds everything. Untyped by design; a feature author narrows it themselves.
 */
export type TableFeature<TRow, Members extends object = object> = (
  core: TableCore<TRow>,
  composed: Record<string, unknown>
) => TableFeatureSpec<TRow, Members>;

import { computed, signal, type Signal } from '@angular/core';
import type { ColumnDef, RenderRow } from '../api/types';
import { foldColumnRules, resolveColumnDefs, type ColumnRuleEntry } from './columns';
import {
  runPipeline,
  type PipelineStages,
  type RenderRowsBuilder,
} from './pipeline';
import { buildDefaultRenderRows, normalizeTrackBy } from './rows';
import type { TableCore, TableEngineConfig } from './types';
import { createWritableView } from './writable-view';

/**
 * What `composeTable()` gets back from core construction. `stages`, `columnRules`, and the
 * render-rows builder are handed out as mutable registries rather than store members — the
 * `rows` / `renderRows` / `columns` computeds read them at *evaluation* time, so features
 * registering during the fold are visible by the time a consumer first reads any of them
 * (ADR-0003).
 */
export interface TableCoreHandle<TRow> {
  readonly core: TableCore<TRow>;
  readonly renderRows: Signal<RenderRow<TRow>[]>;
  readonly stages: PipelineStages<TRow>;
  readonly columnRules: ColumnRuleEntry<TRow>[];
  setRenderRowsBuilder(build: RenderRowsBuilder<TRow>): void;
}

/**
 * Builds the feature-independent half of the store: the writable source signals
 * (`baseColumns`, `data`), the derived `columns`, and the pipeline computeds. Knows nothing
 * about features.
 */
export function createTableCore<TRow>(
  config: TableEngineConfig<TRow>
): TableCoreHandle<TRow> {
  // Normalized once at construction so there's zero branching at render/comparison time.
  const trackBy = normalizeTrackBy(config.trackBy);

  const baseColumns = signal<ColumnDef<TRow>[]>(resolveColumnDefs(config.columns));
  const columnRules: ColumnRuleEntry<TRow>[] = [];
  const columns = computed(() => foldColumnRules(baseColumns(), columnRules));

  const stages: PipelineStages<TRow> = {};
  let buildRenderRows: RenderRowsBuilder<TRow> = buildDefaultRenderRows(trackBy);

  const rows = computed(() => runPipeline(config.data(), stages));

  // Maps a row's trackBy id to its position in `data()` — the source of `sourceIndex`,
  // stamped below. Built from `data()` directly (not `rows()`, the pipeline output), so a
  // filter/group/sort/expand stage reordering or dropping rows doesn't change what index a
  // surviving row resolves to.
  const indexById = computed(() => {
    const map = new Map<ReturnType<typeof trackBy>, number>();
    config.data().forEach((row, index) => map.set(trackBy(row), index));
    return map;
  });

  // Downstream of `rows` (the pipeline output), not `data` directly — recomputes on every
  // filter/group/sort/expand change, not just when the consumer's `data` signal re-emits.
  // `index` and `sourceIndex` are assigned here, centrally, rather than by each `renderRows`
  // builder: `index` is purely the row's position in the final array (ADR-0005's
  // `aria-rowindex` source), and `sourceIndex` resolves via `indexById` — `undefined` for a
  // synthesized row (`row.data === null`) since there is no `data()` entry to point to.
  const renderRows = computed(() => {
    const byId = indexById();
    return buildRenderRows(rows()).map((row, index) => ({
      ...row,
      index,
      sourceIndex: row.data === null ? undefined : byId.get(row.id),
    }));
  });

  const core: TableCore<TRow> = {
    columns: createWritableView(
      () => columns(),
      (updater) => baseColumns.update(updater)
    ),
    baseColumns: baseColumns.asReadonly(),
    rows,
    trackBy,
    indexById,
    value: createWritableView(
      () => config.data(),
      (updater) => config.data.update((rows) => updater(rows, { trackBy }))
    ),
  };

  return {
