  /**
   * Decides whether a row should render the expand toggle, independent of whether its
   * children are loaded yet. Use this for lazy-loaded children (fetched on expand), where
   * `childrenAccessor` legitimately returns `undefined`/`[]` until the row has been opened
   * at least once. Default: derived from `childrenAccessor` (non-empty array required).
   */
  isExpandable?: (row: TRow) => boolean;
}

/** The slice of the core store this feature reads. */
type ExpansionInput<TRow> = Pick<TableCore<TRow>, 'rows' | 'trackBy'>;

export interface ExpansionMembers {
  readonly expandedRows: Signal<Set<RowId>>;

  // Additive-only: every id expanded at least once. Never shrinks on collapse — lets
  // consumers gate lazy-then-persist detail-panel mounting on `everExpanded().has(id)`
  // instead of `isExpanded`. See docs/1-state/features/expansion.md.
  readonly everExpanded: Signal<Set<RowId>>;

  readonly rowExpanded: Observable<RowId>;

  toggleExpanded(rowId: RowId): void;
  expandAll(): void;
  collapseAll(): void;
}

function hasChildrenField<TRow>(
  row: TRow
): row is TRow & { children?: TRow[] } {
  return typeof row === 'object' && row !== null && 'children' in row;
}

function defaultChildrenAccessor<TRow>(row: TRow): TRow[] | undefined {
  return hasChildrenField(row) ? row.children : undefined;
}

function hasNonEmptyChildren<TRow>(children: TRow[] | undefined): children is TRow[] {
  return !!children && children.length > 0;
}

function buildExpansionRenderRows<TRow>(
  rows: TRow[],
  trackBy: TrackByFn<TRow>,
  expandedRows: Set<RowId>,
  childrenAccessor: (row: TRow) => TRow[] | undefined,
  isExpandable: (row: TRow) => boolean,
  depth = 0
): Omit<RenderRow<TRow>, 'index'>[] {
  return rows.flatMap((row) => {
    const id = trackBy(row);
    const children = childrenAccessor(row);
    const hasChildren = isExpandable(row);
    const isExpanded = expandedRows.has(id);
    const self: Omit<RenderRow<TRow>, 'index'> = {
      id,
      depth,
      kind: 'row',
      data: row,
      hasChildren,
      isExpanded,
    };
    const nested = hasNonEmptyChildren(children) && isExpanded
      ? buildExpansionRenderRows(children, trackBy, expandedRows, childrenAccessor, isExpandable, depth + 1)
      : [];
    return [self, ...nested];
  });
}

// Recursively collects the id of every expandable row, at any depth — used by `expandAll()`
// to seed `expandedRows`. Only recurses into rows whose children are already loaded; rows
// with lazy/unloaded children still get expanded (and their `rowExpanded` event fires), but
// their own descendants can't be discovered until fetched.
function collectExpandableRowIds<TRow>(
  rows: TRow[],
  trackBy: TrackByFn<TRow>,
  childrenAccessor: (row: TRow) => TRow[] | undefined,
  isExpandable: (row: TRow) => boolean
): RowId[] {
  return rows.flatMap((row) => {
    if (!isExpandable(row)) {
      return [];
    }
    const children = childrenAccessor(row);
    const nested = hasNonEmptyChildren(children)
      ? collectExpandableRowIds(children, trackBy, childrenAccessor, isExpandable)
      : [];
    return [trackBy(row), ...nested];
  });
}

/**
 * Adds multi-expand, tree-capable row expansion to a `createTable()`. Standalone — reads
 * only core members, no dependency on any other feature. Declares `renderRows` to flatten
 * expanded children into `renderRows()` (see with-expansion.md), so it cannot be composed
 * alongside another feature that does the same.
 */
export function withExpansion<TRow = unknown>(config: WithExpansionConfig<TRow> = {}) {
  const childrenAccessor = config.childrenAccessor ?? defaultChildrenAccessor<TRow>;
  const isExpandable =
    config.isExpandable ?? ((row: TRow) => hasNonEmptyChildren(childrenAccessor(row)));

  return (
    core: ExpansionInput<TRow>
  ): TableFeatureSpec<TRow, ExpansionMembers> => {
    const expandedRows = signal(new Set<RowId>());
    const everExpanded = signal(new Set<RowId>());
    const rowExpandedSource = new Subject<RowId>();

    function toggleExpanded(rowId: RowId): void {
      const next = new Set(expandedRows());
      const isCollapsing = next.has(rowId);
      if (isCollapsing) {
        next.delete(rowId);
      } else {
        next.add(rowId);
        everExpanded.update((seen) => new Set(seen).add(rowId));
      }
      expandedRows.set(next);
      rowExpandedSource.next(rowId);
    }

    function expandAll(): void {
      const ids = collectExpandableRowIds(
        core.rows(),
        core.trackBy,
        childrenAccessor,
        isExpandable
      );
      everExpanded.update((seen) => {
        const next = new Set(seen);
        ids.forEach((id) => next.add(id));
        return next;
      });
      expandedRows.set(new Set(ids));
    }

    function collapseAll(): void {
      expandedRows.set(new Set());
    }

    // ADR-0006: `expandedRows` answers "is this row live and expanded" — an id that leaves
    // `data` must leave here too. `everExpanded` answers "has this id ever been expanded" and
    // is deliberately exempt (see its member doc).
    function onRowsRemoved(ids: readonly RowId[]): void {
      const next = pruneByIds(expandedRows(), ids);
      if (next !== expandedRows()) {
        expandedRows.set(new Set(next));
      }
    }

    return {
      members: {
        expandedRows: expandedRows.asReadonly(),
        everExpanded: everExpanded.asReadonly(),
        rowExpanded: rowExpandedSource.asObservable(),
        toggleExpanded,
        expandAll,
        collapseAll,
      },
      renderRows: (rows) =>
        buildExpansionRenderRows(
          rows,
          core.trackBy,
          expandedRows(),
          childrenAccessor,
          isExpandable
        ),
      onRowsRemoved,
    };
  };
}

import { computed, signal, type Signal } from '@angular/core';
import { pruneByIds } from '../../engine/rows';
import type { TableCore, TableFeatureSpec } from '../../engine/types';
import { createWritableView, type WritableView } from '../../engine/writable-view';
import type { EditingState, EditingUpdater } from '../row-edit-mutations';
import type { RowId } from '../types';

/** Sentinel snapshot value: the row did not exist in `data` when `beginEdit` captured it
 * (D28) — the blank-row-add flow. `revertEdit` reads this to remove the row instead of
 * restoring a value. */
export const ABSENT = Symbol('row-edit-absent');

export type RowSnapshot<TRow> = TRow | typeof ABSENT;

/** id -> the row's value at the moment `beginEdit` first captured it (D17), or `ABSENT` (D28).
 * One restore point per row; whether that row is currently open is a separate fact. */
export type SnapshotMap<TRow> = ReadonlyMap<RowId, RowSnapshot<TRow>>;

export interface WithRowEditConfig {
  /** Default `false` (D14): a second `beginEdit` closes whatever row was already open. */
  multiple?: boolean;
}

export interface RowEditMembers<TRow> {
  /** Read: which rows are open for editing. Write: `.update(updater)` (D30) — e.g.
   * `table.editing.update(beginEdit(id))`. Every updater, including the ones that only touch
   * restore points, is applied through this one view. */
  readonly editing: WritableView<ReadonlySet<RowId>, EditingUpdater<TRow>>;
  /** D31: rows closed by `endEdit(id, { keepSnapshot: true })` — visually done, still
   * rollback-able while an optimistic save is in flight. Derived from the state, so a row can
   * never be open and pending at once. */
  readonly pending: Signal<ReadonlySet<RowId>>;
}

const NO_IDS: ReadonlySet<RowId> = new Set();

/**
 * D31: holds a restore point but is no longer open. Derived rather than stored — this is what
 * makes `endEdit`'s "move to pending" a single `open.delete(id)` with no second container to
 * fall out of step with (D31.5).
 */
export function pendingIds<TRow>(state: EditingState<TRow>): ReadonlySet<RowId> {
  const ids = new Set<RowId>();
  for (const id of state.snapshots.keys()) {
    if (!state.open.has(id)) {
      ids.add(id);
    }
  }
  // Shared empty set so the common case (nothing pending) keeps a stable identity and does not
  // invalidate downstream computeds on every open/close. Checked after the scan, not before:
  // a size comparison would depend on `open ⊆ snapshots` holding, and would return a silently
  // wrong answer rather than fail if it ever stopped.
  return ids.size === 0 ? NO_IDS : ids;
}

/**
 * Single mode (D14): keeps only the most recently opened row. The rows it displaces are closed
 * the way `endEdit` does — their restore points go with them, since under D24 whatever the user
 * typed was already committed on blur and keeping it is the unsurprising outcome (D31.2).
 */
function closeAllButLast<TRow>(state: EditingState<TRow>): EditingState<TRow> {
  const ids = [...state.open];
  const snapshots = new Map(state.snapshots);
  for (const displaced of ids.slice(0, -1)) {
    snapshots.delete(displaced);
  }
  return { snapshots, open: new Set(ids.slice(-1)) };
}

/**
 * Adds button-triggered edit-mode tracking (F2b) to a `createTable()` — which rows are
 * currently open for editing, plus their pre-edit restore points for `revertEdit` (D17/D28).
 * Mode gate only: claims no pipeline stage and no `renderRows` slot (D10, `4-increments.md`
 * E3). The consumer's own `form(data)` (D22) owns the actual field values; this feature only
 * tracks which rows show the form's inputs.
 *
 * `{ multiple: true }` combined with optimistic save (D31) is undesigned — N open rows × M
 * in-flight saves — and unsupported until someone specs it (D31.2).
 */
export function withRowEdit<TRow = unknown>(config: WithRowEditConfig = {}) {
  const multiple = config.multiple ?? false;

  return (core: TableCore<TRow>): TableFeatureSpec<TRow, RowEditMembers<TRow>> => {
    // One signal over both facts: `pending` is derived from them together, so it can never
    // read a half-applied write (D31.5).
    const state = signal<EditingState<TRow>>({ snapshots: new Map(), open: new Set() });

    // Enforces D14's single-mode "closes whatever was open" without any updater (beginEdit,
    // etc.) needing to know about `multiple` — every write funnels through here.
    function applyEditingState(next: EditingState<TRow>): void {
      const exceedsSingleMode = !multiple && next.open.size > 1;
      state.set(exceedsSingleMode ? closeAllButLast(next) : next);
    }

    const members = {
      editing: createWritableView<ReadonlySet<RowId>, EditingUpdater<TRow>>(
        () => state().open,
        (updater) =>
          applyEditingState(
            updater(state(), {
              data: core.value(),
              trackBy: core.trackBy,
              writeData: (rows) => core.value.update(() => rows),
            })
          )
      ),
      pending: computed(() => pendingIds(state())),
    };

    // ADR-0006: an id that leaves `data` must leave both `open` (nothing left to show inputs
    // for) and `snapshots` (nothing left to restore) — `pending` needs no pruning of its own,
    // since it is derived from the other two, not stored. `open` is pruned independently of
    // `snapshots`: `pendingIds()` treats "has a snapshot but isn't open" as pending, so leaving
    // a removed id in `open` would surface it as newly pending. `ABSENT` snapshots (D28) are
    // exempt — they were never backed by a row in `data` to begin with.
    function onRowsRemoved(ids: readonly RowId[]): void {
      const current = state();
      const nextOpen = pruneByIds(current.open, ids);
      const nextSnapshots = pruneByIds(current.snapshots, ids, (value) => value === ABSENT);
      if (nextOpen !== current.open || nextSnapshots !== current.snapshots) {
        applyEditingState({ open: nextOpen, snapshots: nextSnapshots });
      }
    }

    return { members, onRowsRemoved } as TableFeatureSpec<TRow, RowEditMembers<TRow>>;
  };
}

import { computed, signal, type Signal } from '@angular/core';
import { Subject, type Observable } from 'rxjs';
import type { TableCore, TableFeatureSpec } from '../../engine/types';
import type { ColumnDef, SortDirection, SortRule } from '../types';

export interface WithSortingConfig {
  manual?: boolean;
  multi?: boolean;
}

/** The slice of the core store this feature reads. */
type SortingInput<TRow> = Pick<TableCore<TRow>, 'columns'>;

export interface SortingMembers {
  readonly sorting: Signal<SortRule[]>;
  readonly sortDirections: Signal<ReadonlyMap<string, SortDirection>>;
  readonly sortChanged: Observable<SortRule[]>;

  toggleSort(columnId: string): void;
  setSorting(rules: SortRule[]): void;
  clearSorting(): void;
}

function toSortDirectionsMap(rules: SortRule[]): ReadonlyMap<string, SortDirection> {
  const directions = new Map<string, SortDirection>();
  for (const rule of rules) {
    directions.set(rule.columnId, rule.direction);
  }
  return directions;
}

function cycleSortRule(rules: SortRule[], columnId: string): SortRule[] {
  const index = rules.findIndex((rule) => rule.columnId === columnId);
  if (index === -1) {
    return [...rules, { columnId, direction: 'asc' }];
  }
  if (rules[index].direction === 'asc') {
    return rules.map((rule, i) =>
      i === index ? { ...rule, direction: 'desc' as const } : rule
    );
  }
  return rules.filter((_, i) => i !== index);
}

function replaceSortRule(rules: SortRule[], columnId: string): SortRule[] {
  const current = rules[0];
  if (!current || current.columnId !== columnId) {
    return [{ columnId, direction: 'asc' }];
  }
  if (current.direction === 'asc') {
    return [{ columnId, direction: 'desc' }];
  }
  return [];
}

function detectComparator<TRow>(
  accessor: (row: TRow) => unknown,
  rows: TRow[]
): (a: TRow, b: TRow) => number {
  const sample = rows.map(accessor).find((value) => value != null);
  if (sample instanceof Date) {
    return (a, b) =>
      (accessor(a) as Date).getTime() - (accessor(b) as Date).getTime();
  }
  if (typeof sample === 'number') {
    return (a, b) => (accessor(a) as number) - (accessor(b) as number);
  }
  // String(), not `.toString()` on the raw value — the spec's fallback is
  // locale string compare via `.toString()`, but individual rows can still hold
  // null/undefined even when the detection sample above found a non-null value
  // elsewhere in the column; String() handles that without throwing.
  return (a, b) =>
    String(accessor(a)).localeCompare(String(accessor(b)));
}

function sortRows<TRow>(
  rows: TRow[],
  rules: SortRule[],
  columns: ColumnDef<TRow>[]
): TRow[] {
  if (rules.length === 0) {
    return rows;
  }
  const columnById = new Map(columns.map((column) => [column.id, column]));
  const comparators = rules.flatMap((rule) => {
    const column = columnById.get(rule.columnId);
    if (!column) {
      return [];
    }
    const compare = column.sortFn ?? detectComparator(column.accessor, rows);
    const sign = rule.direction === 'asc' ? 1 : -1;
    return [(a: TRow, b: TRow) => sign * compare(a, b)];
  });

  return [...rows].sort((a, b) => {
    for (const compare of comparators) {
      const result = compare(a, b);
      if (result !== 0) {
        return result;
      }
    }
    return 0;
  });
}

/**
 * Adds three-state (ascending -> descending -> unsorted) sorting to a
 * `createTable()`. Reads `sortFn` / `enableSorting` directly off the core
 * `columns` config — no compile-time feature dependency (see with-sorting.md).
 *
 * By default (`multi: false`), clicking a column replaces the sort with that
 * column alone. Pass `{ multi: true }` to accumulate a click-ordered,
 * multi-column priority sort instead.
 */
export function withSorting<TRow = unknown>(config: WithSortingConfig = {}) {
  const manual = config.manual ?? false;
  const multi = config.multi ?? false;

  return (core: SortingInput<TRow>): TableFeatureSpec<TRow, SortingMembers> => {
    const sorting = signal<SortRule[]>([]);
    const sortDirections = computed(() => toSortDirectionsMap(sorting()));
    const sortChangedSource = new Subject<SortRule[]>();

    function applySorting(rules: SortRule[]): void {
      sorting.set(rules);
      sortChangedSource.next(rules);
    }

    function toggleSort(columnId: string): void {
      const column = core.columns().find((c) => c.id === columnId);
      const isSortable = !!column && column.enableSorting !== false;
      if (!isSortable) {
        return;
      }
      applySorting(
        multi
          ? cycleSortRule(sorting(), columnId)
          : replaceSortRule(sorting(), columnId)
      );
    }

    return {
      members: {
        sorting: sorting.asReadonly(),
        sortDirections,
        sortChanged: sortChangedSource.asObservable(),
        toggleSort,
        setSorting: applySorting,
        clearSorting: () => applySorting([]),
      },
      stages: {
        sort: (rows) =>
          manual ? rows : sortRows(rows, sorting(), core.columns()),
      },
    };
  };
}

import { computed } from '@angular/core';

/**
 * Store-member write surface (D30): `()` reads the current value, `.update(updater)` writes
 * through to whatever signal backs it. Built the same way Angular's own `signal()` is built —
 * `Object.assign` onto a real `computed()` so the result carries Angular's reactive-node brand
 * and stays a valid `Signal` anywhere one's expected.
 */
export interface WritableView<T, Updater> {
  (): T;
  update(updater: Updater): void;
}

export function createWritableView<T, Updater>(
  read: () => T,
  applyUpdater: (updater: Updater) => void
): WritableView<T, Updater> {
  return Object.assign(computed(read), { update: applyUpdater });
}

