import { Directive, input, type InputSignal } from '@angular/core';

// ADR-0005: dual-tag selector, role set unconditionally. See
// `ngp-table-header-cell.directive.ts` for why this is a separate directive rather than one
// shared directive with an `isHeader` flag.
@Directive({
  selector: 'td[ngpTableCell], div[ngpTableCell]',
  host: {
    role: 'cell',
    '[attr.aria-colindex]': 'ngpTableCell() + 1',
  },
})
export class NgpTableCellDirective {
  // aria-colindex is 1-based per WAI-ARIA; the input is the 0-based column position.
  readonly ngpTableCell: InputSignal<number> = input.required<number>();
}

import { computed, Directive, input, type InputSignal, type Signal } from '@angular/core';

import { NGP_TABLE_STORE } from './tokens';
import type { TableStore } from '../api/types';

// ADR-0005: dual-tag selector, native `<table>` and `<div>` grid share one directive. `role`
// is set unconditionally, even on native `<table>` — an explicit role matching the implicit
// native one is a documented no-op, not a conflict (matches Angular CDK Table's own practice).
@Directive({
  selector: 'table[ngpTable], div[ngpTable]',
  providers: [{ provide: NGP_TABLE_STORE, useExisting: NgpTableDirective }],
  host: {
    role: 'table',
    '[attr.aria-rowcount]': 'ariaRowCount()',
    '[attr.aria-colcount]': 'ariaColCount()',
  },
})
export class NgpTableDirective<TRow = unknown> {
  readonly ngpTable: InputSignal<TableStore<TRow>> = input.required<TableStore<TRow>>();

  readonly ariaRowCount: Signal<number> = computed(() => this.ngpTable().totalRowCount());
  readonly ariaColCount: Signal<number> = computed(() => this.ngpTable().columns().length);
}

import { Directive, input, type InputSignal } from '@angular/core';

// ADR-0005: separate directive from `NgpTableCellDirective`, not a shared directive with an
// `isHeader` boolean — matches Angular CDK's `CdkHeaderCell`/`CdkCell` split. Header-only
// concerns (`aria-sort`, sort-trigger affordance) belong here later, never on the data-cell
// directive's public API. `aria-sort` itself stays owned by the sort feature directive
// (`docs/3-ui/cross-cutting/accessibility.md`), not set by this base directive.
@Directive({
  selector: 'th[ngpTableHeaderCell], div[ngpTableHeaderCell]',
  host: {
    role: 'columnheader',
    '[attr.aria-colindex]': 'ngpTableHeaderCell() + 1',
  },
})
export class NgpTableHeaderCellDirective {
  // aria-colindex is 1-based per WAI-ARIA; the input is the 0-based column position.
  readonly ngpTableHeaderCell: InputSignal<number> = input.required<number>();
}

import { computed, Directive, input, type InputSignal, type Signal } from '@angular/core';

import { NGP_TABLE_ROW } from './tokens';
import type { RenderRow, RowId } from '../api/types';

// ADR-0005: dual-tag selector, role set unconditionally regardless of host tag.
@Directive({
  selector: 'tr[ngpTableRow], div[ngpTableRow]',
  providers: [{ provide: NGP_TABLE_ROW, useExisting: NgpTableRowDirective }],
  host: {
    role: 'row',
    '[attr.data-row-kind]': 'ngpTableRow().kind',
    '[attr.data-depth]': 'ngpTableRow().depth',
    // aria-rowindex is 1-based per WAI-ARIA; `ngpTableRow().index` is the 0-based array position.
    '[attr.aria-rowindex]': 'ngpTableRow().index + 1',
    '[attr.aria-expanded]': 'ngpTableRow().isExpanded ?? null',
  },
})
export class NgpTableRowDirective<TRow = unknown> {
  readonly ngpTableRow: InputSignal<RenderRow<TRow>> = input.required<RenderRow<TRow>>();

  readonly rowId: Signal<RowId> = computed(() => this.ngpTableRow().id);
  readonly isGroupHeader: Signal<boolean> = computed(() => this.ngpTableRow().kind === 'group');
}

import {
  Directive,
  effect,
  inject,
  input,
  TemplateRef,
  ViewContainerRef,
  type EmbeddedViewRef,
  type InputSignal,
} from '@angular/core';
import type { FieldTree } from '@angular/forms/signals';

import { resolveRowField } from './ngp-table-row-field.resolve';
import type { RenderRow } from '../api/types';

export interface NgpTableRowFieldContext<TRow> {
  // Not readonly: the directive mutates these in place on `sourceIndex` change instead of
  // recreating the embedded view (matches `NgIfContext`'s own mutable-field pattern).
  $implicit: FieldTree<TRow>;
  ngpTableRowField: FieldTree<TRow>;
}

/**
 * Structural directive folding the E2 pattern —
 * `@if (row.sourceIndex !== undefined) { @let field = rows[row.sourceIndex]; }` — into one
 * template line. See D33, `docs/1-state/work/with-row-editing/2-decisions.md`, for why this
 * lives behind the `@acme/table/forms` secondary entry point rather than the root barrel.
 */
@Directive({ selector: '[ngpTableRowField]' })
export class NgpTableRowFieldDirective<TRow> {
  private readonly templateRef =
    inject<TemplateRef<NgpTableRowFieldContext<TRow>>>(TemplateRef);
  private readonly viewContainerRef = inject(ViewContainerRef);

  private viewRef: EmbeddedViewRef<NgpTableRowFieldContext<TRow>> | null = null;

  readonly ngpTableRowField: InputSignal<RenderRow<TRow>> = input.required<RenderRow<TRow>>();
  readonly ngpTableRowFieldFrom: InputSignal<FieldTree<TRow[]>> =
    input.required<FieldTree<TRow[]>>();

  static ngTemplateContextGuard<TRow>(
    _dir: NgpTableRowFieldDirective<TRow>,
    _ctx: unknown
  ): _ctx is NgpTableRowFieldContext<TRow> {
    return true;
  }

  constructor() {
    effect(() => {
      const field = resolveRowField(this.ngpTableRowFieldFrom(), this.ngpTableRowField());
      if (field === undefined) {
        this.viewRef = null;
        this.viewContainerRef.clear();
        return;
      }
      if (this.viewRef === null) {
        this.viewRef = this.viewContainerRef.createEmbeddedView(this.templateRef, {
          $implicit: field,
          ngpTableRowField: field,
        });
        return;
      }
      this.viewRef.context.$implicit = field;
      this.viewRef.context.ngpTableRowField = field;
    });
  }
}

